CREATE TABLE IF NOT EXISTS glitter_history (id INTEGER PRIMARY KEY, era TEXT NOT NULL, topic TEXT NOT NULL, summary TEXT NOT NULL, source_url TEXT NOT NULL, review_status TEXT NOT NULL DEFAULT 'reviewed');
INSERT OR IGNORE INTO glitter_history VALUES (1,'Prehistory','Natural sparkle','Reflective minerals including mica were used in pigments and decoration.','https://www.euclidlibrary.org/content/glitter','reviewed');
INSERT OR IGNORE INTO glitter_history VALUES (2,'Ancient civilizations','Mineral pigments','Mineral pigments such as malachite and mica produced shimmer in cosmetics and architectural finishes.','https://www.themorgan.org/blog/its-shiny-its-sparkly-its-glitter','reviewed');
INSERT OR IGNORE INTO glitter_history VALUES (3,'Pre-industrial','Glass and metallic sparkle','Glass glitter and metallic decorations preceded modern plastic glitter.','https://static1.squarespace.com/static/5aacaec7c258b40bb8770222/t/6566f2c0b61bd6053e6cb53a/1701245700283/Scroll_vol3_2023_Nov.pdf','reviewed');
INSERT OR IGNORE INTO glitter_history VALUES (4,'1930s','Henry Ruschmann','Modern machine-cut glitter is commonly credited to Henry Ruschmann in New Jersey.','https://udspace.udel.edu/bitstream/handle/19716/29519/Mapstone_udel_0060M_14566.pdf?sequence=1','reviewed');
INSERT OR IGNORE INTO glitter_history VALUES (5,'Today','Materials and impacts','Reflective film glitter has uses in art and cosmetics and creates environmental concerns when shed as microplastics.','https://www.themorgan.org/blog/its-shiny-its-sparkly-its-glitter','reviewed');
